m = glow_material("M_RmClearColour")
connect_prop(custom(m, -400, 0, CLEAR_SHADE, F3, [("C", (coll(m, mpc, "ClearColour", -750, 0), "")),
                                                   ("WP", (expr(m, unreal.MaterialExpressionWorldPosition, -750, 200), "")),
                                                   ("Cam", (expr(m, unreal.MaterialExpressionCameraPositionWS, -750, 280), "")),
                                                   ("T", (coll(m, rm, "WorldTime", -750, 360), "")),
                                                   ("Clouds", (coll(m, rm, "Clouds", -750, 440), ""))], "RmClearColour"), "",
             unreal.MaterialProperty.MP_EMISSIVE_COLOR)
finish(m)

for name, glass in (("M_RmProp_Translucent", False), ("M_RmPropGlass", True)):
  m = recreate(name, unreal.Material, unreal.MaterialFactoryNew())
  if glass:
    # The soft layers of glass and water props (SimData/<track>.surfacelook.txt): lit, a mirror finish, Lumen's
    # front-layer reflections (Remastered post-process volume).
    m.set_editor_property("shading_model", unreal.MaterialShadingModel.MSM_DEFAULT_LIT)
    m.set_editor_property("translucency_lighting_mode", unreal.TranslucencyLightingMode.TLM_SURFACE_PER_PIXEL_LIGHTING)
  else:
    m.set_editor_property("shading_model", unreal.MaterialShadingModel.MSM_UNLIT)
  m.set_editor_property("blend_mode", unreal.BlendMode.BLEND_TRANSLUCENT)
  m.set_editor_property("two_sided", True)
  m.set_editor_property("use_translucency_vertex_fog", False)
  m.set_editor_property("allow_translucent_custom_depth_writes", True)
  m.set_editor_property("opacity_mask_clip_value", 1.0 / 256.0)
  base = tex_param(m, "BaseTex", -1100, -200)
  uv0 = expr(m, unreal.MaterialExpressionTextureCoordinate, -1700, -200, coordinate_index=0)
  su = expr(m, unreal.MaterialExpressionScalarParameter, -1700, -100, parameter_name="UVScrollU", default_value=0.0)
  sv = expr(m, unreal.MaterialExpressionScalarParameter, -1700, 0, parameter_name="UVScrollV", default_value=0.0)
  suv = expr(m, unreal.MaterialExpressionAppendVector, -1500, -50)
  connect(su, "", suv, "A")
  connect(sv, "", suv, "B")
  uvs = expr(m, unreal.MaterialExpressionAdd, -1300, -150)
  connect(uv0, "", uvs, "A")
  connect(suv, "", uvs, "B")
  connect(uvs, "", base, "UVs")
  vc = expr(m, unreal.MaterialExpressionVertexColor, -1000, 100)
  shade = custom(m, -400, 0, PROP_SOFT_SHADE, F3, [("Tex", (base, "RGB")), ("VC", (vc, ""))], "RmPropSoftShade")
  if glass:
    tint = expr(m, unreal.MaterialExpressionMultiply, -200, -60)
    connect(shade, "", tint, "A")
    connect(expr(m, unreal.MaterialExpressionConstant, -400, -100, r=0.6), "", tint, "B")
    connect_prop(tint, "", unreal.MaterialProperty.MP_BASE_COLOR)
    glow = expr(m, unreal.MaterialExpressionMultiply, -200, 40)
    connect(shade, "", glow, "A")
    connect(expr(m, unreal.MaterialExpressionConstant, -400, 60, r=0.25), "", glow, "B")
    connect_prop(glow, "", unreal.MaterialProperty.MP_EMISSIVE_COLOR)
    connect_prop(expr(m, unreal.MaterialExpressionConstant, -400, 140, r=0.03), "", unreal.MaterialProperty.MP_ROUGHNESS)
    connect_prop(expr(m, unreal.MaterialExpressionConstant, -400, 200, r=1.0), "", unreal.MaterialProperty.MP_SPECULAR)
  else:
    connect_prop(shade, "", unreal.MaterialProperty.MP_EMISSIVE_COLOR)
  gs_a = custom(m, -1000, 400, PROP_GS_ALPHA, F1, [("A", (base, "A")), ("VA", (vc, "A"))], "PropGsAlpha")
  alpha = custom(m, -800, 400, PROP_BLEND, F1, [("As", (gs_a, "")), ("Tex", (base, "RGB")), ("VC", (vc, ""))], "PropBlend")
  depth = expr(m, unreal.MaterialExpressionPixelDepth, -700, 500)
  cd = expr(m, unreal.MaterialExpressionSceneTexture, -1000, 650, scene_texture_id=unreal.SceneTextureId.PPI_CUSTOM_DEPTH)
  front = custom(m, -800, 650, SOFT_DEPTH, F1, [("PD", (depth, "")), ("CD", (cd, "Color"))], "SoftDepth")
  vis = expr(m, unreal.MaterialExpressionMultiply, -550, 450)
  connect(alpha, "", vis, "A")
  connect(front, "", vis, "B")
  if glass:
    vis = custom(m, -450, 450, GLASS_OPACITY, F1, [("A", (vis, "")), ("F", (expr(m, unreal.MaterialExpressionFresnel, -650, 380), ""))],
                 "GlassOpacity")
  op = custom(m, -300, 550, DRAW_CLIP, F1,
              [("Depth", (depth, "")), ("DrawDistance", (coll(m, mpc, "DrawDistance", -700, 600), "")),
               ("Scale", (coll(m, rm, "DrawDistanceScale", -700, 660), "")), ("Alpha", (vis, ""))],
              "DrawClip")
  connect_prop(op, "", unreal.MaterialProperty.MP_OPACITY)
  finish(m)

m = recreate("M_RmTrailStamp", unreal.Material, unreal.MaterialFactoryNew())
m.set_editor_property("shading_model", unreal.MaterialShadingModel.MSM_UNLIT)
m.set_editor_property("blend_mode", unreal.BlendMode.BLEND_ADDITIVE)
strength = expr(m, unreal.MaterialExpressionScalarParameter, -700, 100, parameter_name="Strength", default_value=0.35)
connect_prop(custom(m, -300, 0, STAMP, F1, [("UV", (expr(m, unreal.MaterialExpressionTextureCoordinate, -700, 0), "")),
                                           ("Strength", (strength, ""))], "TrailStamp"), "", unreal.MaterialProperty.MP_EMISSIVE_COLOR)
finish(m)

m = recreate("M_RmTrailShift", unreal.Material, unreal.MaterialFactoryNew())
m.set_editor_property("shading_model", unreal.MaterialShadingModel.MSM_UNLIT)
prev = expr(m, unreal.MaterialExpressionTextureObjectParameter, -700, 100, parameter_name="Prev")
prev.set_editor_property("texture", unreal.load_asset("/Engine/EngineResources/Black"))
prev.set_editor_property("sampler_type", unreal.MaterialSamplerType.SAMPLERTYPE_LINEAR_GRAYSCALE)
off = expr(m, unreal.MaterialExpressionVectorParameter, -700, 200, parameter_name="Offset", default_value=unreal.LinearColor(0, 0, 0, 0))
offm = expr(m, unreal.MaterialExpressionComponentMask, -500, 200, r=True, g=True, b=False, a=False)
connect(off, "", offm, "")
connect_prop(custom(m, -300, 0, SHIFT, F1, [("UV", (expr(m, unreal.MaterialExpressionTextureCoordinate, -700, 0), "")),
                                           ("Offset", (offm, "")), ("Prev", (prev, ""))], "TrailShift"), "",
             unreal.MaterialProperty.MP_EMISSIVE_COLOR)
finish(m)

# Lens halos / sun flare (SSXLensFX): the Classic additive materials output display values, which added in linear light
# turned the lamp halos into large pink glows; the Remastered copies decode them first.
for classic, name in (("M_SSXLensSprite", "M_RmLensSprite"), ("M_SSXLensFan", "M_RmLensFan")):
    if assets.does_asset_exist(f"{PATH}/{name}"):
        assets.delete_asset(f"{PATH}/{name}")
    m = assets.duplicate_asset(f"/Game/Particles/{classic}", f"{PATH}/{name}")
    src = mel.get_material_property_input_node(m, unreal.MaterialProperty.MP_EMISSIVE_COLOR)
    # Halfway between the display value and its decode: fully decoded the halos all but vanished.
    dec = custom(m, 0, 0, f"return lerp(saturate(C), {DEC.format(x='saturate(C)')}, 0.5);", F3, [("C", (src, ""))], "RmLensDecode")
    connect_prop(dec, "", unreal.MaterialProperty.MP_EMISSIVE_COLOR)
    finish(m)

pp = recreate("PP_RmScene", unreal.Material, unreal.MaterialFactoryNew())
pp.set_editor_property("material_domain", unreal.MaterialDomain.MD_POST_PROCESS)
pp.set_editor_property("blendable_location", unreal.BlendableLocation.BL_REPLACING_TONEMAPPER)
scene = expr(pp, unreal.MaterialExpressionSceneTexture, -700, 0, scene_texture_id=unreal.SceneTextureId.PPI_POST_PROCESS_INPUT0)
bloom = expr(pp, unreal.MaterialExpressionSceneTexture, -700, 100, scene_texture_id=unreal.SceneTextureId.PPI_POST_PROCESS_INPUT2)   # combined bloom
sm = expr(pp, unreal.MaterialExpressionSceneTexture, -700, 200, scene_texture_id=unreal.SceneTextureId.PPI_SHADING_MODEL_ID)
enc = custom(pp, -350, 0, PP_SCENE, F3,
             [("Scene", (scene, "Color")), ("Bloom", (bloom, "Color")), ("SM", (sm, "Color")),
              ("Brightness", (coll(pp, mpc, "Brightness", -700, 400), "")),
              ("Exposure", (coll(pp, rm, "Exposure", -700, 500), "")),
              ("Saturation", (coll(pp, rm, "Saturation", -700, 600), ""))], "RmScene")
connect_prop(enc, "", unreal.MaterialProperty.MP_EMISSIVE_COLOR)
finish(pp)

# The shadow twins of props with a soft (translucent) layer: that slot clipped, so the twin stays Nanite
# (USSXRemasterWorld::ApplyTranslucentProps).
m = lit_material("M_RmShadowHole", unreal.BlendMode.BLEND_MASKED)
connect_prop(expr(m, unreal.MaterialExpressionConstant, -400, 300, r=0.0), "", unreal.MaterialProperty.MP_OPACITY_MASK)
finish(m)

